-- Optional onboarding preferences. Topic vectors are authored and versioned on
-- the server, in the same pinned embedding space as the text index.
create table recsys.interest_catalogs (
    version integer primary key check (version>0),
    active boolean not null default false
);
create unique index interest_catalog_one_active on recsys.interest_catalogs(active) where active;
insert into recsys.interest_catalogs(version,active) values(1,true);

create table recsys.interest_topics (
    catalog_version integer not null references recsys.interest_catalogs(version),
    id text not null check (id~'^[a-z][a-z0-9_-]{0,31}$'),
    ordinal smallint not null check (ordinal between 1 and 64),
    label_ru text not null,
    label_en text not null,
    space text not null,
    embedding extensions.vector(384) not null check(extensions.vector_norm(embedding) between .999 and 1.001),
    primary key(catalog_version,id),
    unique(catalog_version,ordinal)
);
create table recsys.user_topic_choices (
    user_id uuid primary key references recsys.user_states(user_id) on delete cascade,
    epoch integer not null check(epoch>0),
    version bigint not null check(version>0),
    catalog_version integer not null references recsys.interest_catalogs(version),
    topics text[] not null check(cardinality(topics)<=4)
);
create index user_topic_choices_catalog on recsys.user_topic_choices(catalog_version);
create table recsys.topic_write_receipts (
    user_id uuid not null references recsys.user_states(user_id) on delete cascade,
    request_id uuid not null,
    received_at timestamptz not null default statement_timestamp(),
    payload jsonb not null,
    response jsonb not null,
    primary key(user_id,request_id)
);
create index topic_write_receipts_recent on recsys.topic_write_receipts(user_id,received_at desc,request_id desc);

alter table recsys.interest_catalogs enable row level security;
alter table recsys.interest_topics enable row level security;
alter table recsys.user_topic_choices enable row level security;
alter table recsys.topic_write_receipts enable row level security;
revoke all on recsys.interest_catalogs,recsys.interest_topics,recsys.user_topic_choices,recsys.topic_write_receipts
    from public,anon,authenticated,service_role,yap_recommendation_worker,yap_feed_media_worker,yap_feed_vision_worker;

alter table recsys.feed_snapshots add column topics_catalog_version integer,
    add column topics_choice_version bigint;

-- Same atomic quota counters and fixed windows as the existing social RPCs.
create or replace function private.consume_social_quota(op text)
returns void language plpgsql security definer set search_path='' as $$
declare per_min integer;per_day integer;accepted integer;today date:=(statement_timestamp() at time zone 'UTC')::date;
begin
 case op
 when 'follow_write' then per_min:=120;per_day:=2000;
 when 'follow_create' then per_min:=30;per_day:=500;
 when 'follow_state_read' then per_min:=120;per_day:=86400;
 when 'following_read' then per_min:=60;per_day:=86400;
 when 'followers_read' then per_min:=60;per_day:=86400;
 when 'comment_create' then per_min:=30;per_day:=500;
 when 'comment_create_request' then per_min:=60;per_day:=86400;
 when 'comment_edit' then per_min:=30;per_day:=1000;
 when 'comment_delete' then per_min:=60;per_day:=1000;
 when 'comment_action' then per_min:=120;per_day:=20000;
 when 'comment_read' then per_min:=60;per_day:=86400;
 when 'report_post' then per_min:=5;per_day:=20;
 when 'report_comment' then per_min:=5;per_day:=30;
 when 'report_request' then per_min:=60;per_day:=86400;
 when 'nearby_read' then per_min:=60;per_day:=86400;
 when 'friends_read' then per_min:=60;per_day:=86400;
 when 'topics_read' then per_min:=60;per_day:=1000;
 when 'topics_write' then per_min:=12;per_day:=120;
 else raise exception using errcode='22023',message='invalid_social_operation';end case;
 insert into private.feed_social_limits as q(user_id,operation,window_started_at,requests,day_utc,day_count)
 values(auth.uid(),op,statement_timestamp(),1,today,1)
 on conflict(user_id,operation)do update set
 window_started_at=case when q.window_started_at<=statement_timestamp()-interval '1 minute'then statement_timestamp()else q.window_started_at end,
 requests=case when q.window_started_at<=statement_timestamp()-interval '1 minute'then 1 else q.requests+1 end,
 day_utc=today,day_count=case when q.day_utc<today then 1 else q.day_count+1 end
 where(q.window_started_at<=statement_timestamp()-interval '1 minute'or q.requests<per_min)and(q.day_utc<today or q.day_count<per_day)
 returning requests into accepted;
 if accepted is null then raise exception using errcode='42901',message='social_rate_limited';end if;
end $$;

create function private.recommendation_topic_selection(epoch integer, version bigint, topics text[])
returns jsonb language sql immutable set search_path='' as $$
    select jsonb_build_object('epoch',epoch,'version',coalesce(version,0),
        'status',case when version is null then 'not_set' when cardinality(topics)=0 then 'skipped' else 'selected' end,
        'topics',coalesce(topics,'{}'::text[]))
$$;

create function private.get_recommendation_topics_impl(requested_language text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
    perform private.require_social_account();
    perform private.consume_social_quota('topics_read');
    if requested_language is null or requested_language not in ('ru','en') then
        raise exception using errcode='22023',message='invalid_topic_language';
    end if;
    select jsonb_build_object('catalog_version',catalog.version,'max_selected',4,
      'topics',(select coalesce(jsonb_agg(jsonb_build_object('id',t.id,
        'label',case requested_language when 'ru' then t.label_ru else t.label_en end) order by t.ordinal),'[]'::jsonb)
        from recsys.interest_topics t where t.catalog_version=catalog.version),
      'selection',private.recommendation_topic_selection(coalesce(u.epoch,1),c.version,c.topics))
    into strict result from recsys.interest_catalogs catalog
    left join recsys.user_states u on u.user_id=auth.uid()
    left join recsys.user_topic_choices c on c.user_id=u.user_id and c.epoch=u.epoch
    where catalog.active;
    return result;
end $$;

create function private.set_recommendation_topics_impl(requested_id uuid, expected_epoch integer,
    expected_version bigint, requested_catalog_version integer, requested_topics text[])
returns jsonb language plpgsql security definer set search_path='' as $$
declare viewer uuid:=auth.uid(); s recsys.user_states%rowtype; c recsys.user_topic_choices%rowtype;
    canonical text[]; catalog_id integer; payload jsonb; prior recsys.topic_write_receipts%rowtype;
    next_version bigint; response jsonb; matching integer; changed boolean;
begin
    perform private.require_social_account();
    perform private.consume_social_quota('topics_write');
    if requested_id is null or expected_epoch is null or expected_epoch<1 or expected_version is null
       or expected_version<0 or requested_catalog_version is null or requested_topics is null
       or cardinality(requested_topics)>4 or coalesce(array_ndims(requested_topics),1)<>1
       or octet_length(array_to_string(requested_topics,','))>131
       or exists(select 1 from unnest(requested_topics)t(id) where t.id is null or t.id!~'^[a-z][a-z0-9_-]{0,31}$') then
        raise exception using errcode='22023',message='invalid_topic_selection';
    end if;
    select coalesce(array_agg(distinct t.id order by t.id),'{}'::text[]) into canonical from unnest(requested_topics)t(id);
    if cardinality(canonical)<>cardinality(requested_topics) then
        raise exception using errcode='22023',message='duplicate_topic';
    end if;
    s:=private.lock_recommendation_user(viewer);
    if s.epoch<>expected_epoch then raise exception using errcode='PT409',message='topic_epoch_conflict'; end if;
    select version into strict catalog_id from recsys.interest_catalogs where active;
    if catalog_id<>requested_catalog_version then
        raise exception using errcode='PT409',message='topic_catalog_conflict';
    end if;
    payload:=jsonb_build_array(expected_epoch,expected_version,catalog_id,to_jsonb(canonical));
    select * into prior from recsys.topic_write_receipts where user_id=viewer and request_id=requested_id;
    if found then
        if prior.payload<>payload then raise exception using errcode='PT409',message='topic_request_conflict'; end if;
        return prior.response || jsonb_build_object('replayed',true);
    end if;
    select * into c from recsys.user_topic_choices where user_id=viewer and epoch=s.epoch;
    if coalesce(c.version,0)<>expected_version then raise exception using errcode='PT409',message='topic_version_conflict'; end if;
    select count(*) into matching from recsys.interest_topics t where t.catalog_version=catalog_id and t.id=any(canonical);
    if matching<>cardinality(canonical) then raise exception using errcode='22023',message='unknown_topic'; end if;
    changed:=coalesce(c.topics,'{}'::text[])<>canonical
        or (cardinality(canonical)>0 and c.catalog_version is distinct from catalog_id);
    next_version:=coalesce(c.version,0);
    if changed or c.version is null or c.catalog_version<>catalog_id then
        next_version:=next_version+1;
        insert into recsys.user_topic_choices(user_id,epoch,version,catalog_version,topics)
            values(viewer,s.epoch,next_version,catalog_id,canonical)
        on conflict(user_id) do update set epoch=excluded.epoch,version=excluded.version,
            catalog_version=excluded.catalog_version,topics=excluded.topics;
    end if;
    if changed then
        -- New sessions must not use a pool built from the old choice. Existing
        -- sessions retain their immutable page ordering within this epoch.
        update recsys.user_states set revision=revision+1,current_snapshot=null,prepared_at=null,profile_complete=false
            where user_id=viewer returning * into s;
        perform private.queue_recommendation_refresh(viewer,s.revision,true);
        -- A build started without a topic prior would use the base publisher.
        -- Revoke that lease too, so no pre-change build can become current.
        update recsys.refresh_jobs set lease=null,locked_until=null,claimed_at=null
            where user_id=viewer and lease is not null;
    end if;
    response:=private.recommendation_topic_selection(s.epoch,next_version,canonical)
        || jsonb_build_object('request_id',requested_id,'catalog_version',catalog_id,'replayed',false);
    insert into recsys.topic_write_receipts(user_id,request_id,payload,response) values(viewer,requested_id,payload,response);
    delete from recsys.topic_write_receipts r where r.user_id=viewer and r.request_id in (
        select receipt.request_id from recsys.topic_write_receipts receipt where receipt.user_id=viewer
        order by receipt.received_at desc,receipt.request_id desc offset 32
    );
    return response;
end $$;

create function public.get_recommendation_topics(requested_language text default 'ru')
returns jsonb language sql security invoker set search_path='' as $$
    select private.get_recommendation_topics_impl(requested_language)
$$;
create function public.set_recommendation_topics(requested_id uuid, expected_epoch integer, expected_version bigint,
    requested_catalog_version integer, requested_topics text[])
returns jsonb language sql security invoker set search_path='' as $$
    select private.set_recommendation_topics_impl(requested_id,expected_epoch,expected_version,requested_catalog_version,requested_topics)
$$;

create function private.reset_recommendation_topics()
returns trigger language plpgsql security definer set search_path='' as $$
begin
    delete from recsys.user_topic_choices where user_id=new.user_id;
    delete from recsys.topic_write_receipts where user_id=new.user_id;
    return null;
end $$;
create trigger reset_recommendation_topics after update of epoch on recsys.user_states
    for each row when(old.epoch is distinct from new.epoch) execute function private.reset_recommendation_topics();

-- The worker already reads a leased profile. Extend its response without an
-- extra connection or an RPC during page reads. The old worker can ignore it.
alter function recsys.load_refresh_profile(uuid,uuid,text) rename to load_refresh_profile_base;
create function recsys.load_refresh_profile(viewer uuid, requested_lease uuid, requested_model text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare base jsonb; prior jsonb;
begin
    base:=recsys.load_refresh_profile_base(viewer,requested_lease,requested_model);
    select jsonb_build_object('version',c.version,'catalog_version',c.catalog_version,
        'vectors',jsonb_agg(t.embedding::text order by t.id))
    into prior from recsys.user_topic_choices c
    join recsys.interest_catalogs catalog on catalog.version=c.catalog_version and catalog.active
    join recsys.interest_topics t on t.catalog_version=c.catalog_version and t.id=any(c.topics) and t.space=requested_model
    where c.user_id=viewer and c.epoch=(base->>'epoch')::integer
    group by c.version,c.catalog_version;
    if prior is null then return base; end if;
    return base || jsonb_build_object('topic_prior',prior);
end $$;

create function recsys.publish_topic_recommendations(viewer uuid, requested_lease uuid, result jsonb, visual boolean)
returns boolean language plpgsql security definer set search_path='' as $$
declare accepted boolean; choice recsys.user_topic_choices%rowtype; observed jsonb:=result->'topic_context';
begin
    if jsonb_typeof(observed) is distinct from 'object' or visual is null then
        raise exception using errcode='22023',message='missing_topic_context';
    end if;
    if visual then
        accepted:=recsys.publish_vision_recommendations(viewer,requested_lease,result);
    else
        accepted:=recsys.publish_recommendations(viewer,requested_lease,result);
    end if;
    if not accepted then return false; end if;
    -- The base publisher holds this user's state lock. Topic changes and reset
    -- take the same lock. Failure here rolls back its entire publication.
    select c.* into choice from recsys.user_topic_choices c
    join recsys.interest_catalogs catalog on catalog.version=c.catalog_version and catalog.active
    where c.user_id=viewer;
    if not found or choice.epoch is distinct from (result->>'epoch')::integer
       or choice.version is distinct from (observed->>'version')::bigint
       or choice.catalog_version is distinct from (observed->>'catalog_version')::integer
       or cardinality(choice.topics)=0 then
        raise exception using errcode='40001',message='topic_prior_changed';
    end if;
    update recsys.feed_snapshots s
    set policy_version=case when visual then 'hybrid-v2-vision-topics-v1' else 'hybrid-v2-topics-v1' end,
        topics_catalog_version=choice.catalog_version,topics_choice_version=choice.version
    from recsys.user_states u where u.user_id=viewer and s.id=u.current_snapshot;
    return true;
end $$;

revoke all on function private.recommendation_topic_selection(integer,bigint,text[]),
    private.get_recommendation_topics_impl(text),private.set_recommendation_topics_impl(uuid,integer,bigint,integer,text[]),
    private.reset_recommendation_topics(),public.get_recommendation_topics(text),
    public.set_recommendation_topics(uuid,integer,bigint,integer,text[]),
    recsys.load_refresh_profile_base(uuid,uuid,text),recsys.load_refresh_profile(uuid,uuid,text),
    recsys.publish_topic_recommendations(uuid,uuid,jsonb,boolean)
    from public,anon,authenticated,service_role,yap_recommendation_worker,yap_feed_media_worker,yap_feed_vision_worker;
grant execute on function public.get_recommendation_topics(text),private.get_recommendation_topics_impl(text),
    public.set_recommendation_topics(uuid,integer,bigint,integer,text[]),
    private.set_recommendation_topics_impl(uuid,integer,bigint,integer,text[]) to authenticated;
grant execute on function recsys.load_refresh_profile(uuid,uuid,text),
    recsys.publish_topic_recommendations(uuid,uuid,jsonb,boolean) to yap_recommendation_worker;

